import{_ as e,b as t,f as o,I as l}from"./chunks/framework.DYvp_Vyw.js";const s=JSON.parse('{"title":"Java期末复习笔记 - 第一章 - Java语言概述","description":"","frontmatter":{"title":"Java期末复习笔记 - 第一章 - Java语言概述","date":"2025-05-07T01:48:13.000Z","tags":["Java"],"head":[["meta",{"name":"descriptionx x x","content":"vitepress-theme-bluearchive Tags"}],["meta",{"name":"keywords","content":"vitepress theme bluearchive Tags"}]]},"headers":[],"relativePath":"posts/Java-Own-Study-001.md","filePath":"posts/Java-Own-Study-001.md"}'),r={name:"posts/Java-Own-Study-001.md"};function i(n,a,d,c,u,h){return o(),t("div",null,a[0]||(a[0]=[l('<p>大二上学期的期末复习笔记。</p><hr><div style="text-align:center;"><h1>Java语言概述</h1></div><h1 id="_1-java语言的特点" tabindex="-1"><u style="text-decoration:underline;text-decoration-color:deepskyblue;">1.Java语言的特点 </u> <a class="header-anchor" href="#_1-java语言的特点" aria-label="Permalink to &quot;&lt;u style=&quot;text-decoration: underline; text-decoration-color: deepskyblue;&quot;&gt;1.Java语言的特点 &lt;/u&gt;&quot;">​</a></h1><h3 id="_1-java语言是一种跨平台-适合于分布式计算环境的面向对象编程语言。" tabindex="-1">1.Java语言是一种跨平台，适合于分布式计算环境的面向对象编程语言。 <a class="header-anchor" href="#_1-java语言是一种跨平台-适合于分布式计算环境的面向对象编程语言。" aria-label="Permalink to &quot;1.Java语言是一种跨平台，适合于分布式计算环境的面向对象编程语言。&quot;">​</a></h3><h3 id="_2-java语言虽然衍生自c-与c-相比java是一个完全面向对象的编程语言。java去掉了c-c-中三个不易掌握的数据类型-指针-联合体和结构体。" tabindex="-1">2.Java语言虽然衍生自C++，与C++相比Java是一个完全面向对象的编程语言。Java去掉了C/C++中三个不易掌握的数据类型：指针，联合体和结构体。 <a class="header-anchor" href="#_2-java语言虽然衍生自c-与c-相比java是一个完全面向对象的编程语言。java去掉了c-c-中三个不易掌握的数据类型-指针-联合体和结构体。" aria-label="Permalink to &quot;2.Java语言虽然衍生自C++，与C++相比Java是一个完全面向对象的编程语言。Java去掉了C/C++中三个不易掌握的数据类型：指针，联合体和结构体。&quot;">​</a></h3><h3 id="_3-java语言以对象为中心-以消息为驱动的面向对象的编程语言。支持封装-继承和多态。" tabindex="-1">3.Java语言以对象为中心，以消息为驱动的面向对象的编程语言。支持封装，继承和多态。 <a class="header-anchor" href="#_3-java语言以对象为中心-以消息为驱动的面向对象的编程语言。支持封装-继承和多态。" aria-label="Permalink to &quot;3.Java语言以对象为中心，以消息为驱动的面向对象的编程语言。支持封装，继承和多态。&quot;">​</a></h3><h3 id="_4-java语言是与平台无关的语言-也就是说他有很好的跨平台性。" tabindex="-1">4.Java语言是与平台无关的语言，也就是说他有很好的跨平台性。 <a class="header-anchor" href="#_4-java语言是与平台无关的语言-也就是说他有很好的跨平台性。" aria-label="Permalink to &quot;4.Java语言是与平台无关的语言，也就是说他有很好的跨平台性。&quot;">​</a></h3><h3 id="_5-java支持数据分布和操作分布。" tabindex="-1">5.Java支持数据分布和操作分布。 <a class="header-anchor" href="#_5-java支持数据分布和操作分布。" aria-label="Permalink to &quot;5.Java支持数据分布和操作分布。&quot;">​</a></h3><blockquote><p>分布式包括数据分布和操作分布</p></blockquote><h3 id="_6-java具有较高的安全性。" tabindex="-1">6.Java具有较高的安全性。 <a class="header-anchor" href="#_6-java具有较高的安全性。" aria-label="Permalink to &quot;6.Java具有较高的安全性。&quot;">​</a></h3><h3 id="_7-java语言支持多线程。" tabindex="-1">7.Java语言支持多线程。 <a class="header-anchor" href="#_7-java语言支持多线程。" aria-label="Permalink to &quot;7.Java语言支持多线程。&quot;">​</a></h3><ul><li>一方面，Java环境本身就是多线程的。</li><li>另一方面，Java语言内置多线程机制，可以大大简化多线程应用程序开发。</li></ul><h3 id="_8-java支持网络编程-可以处理tcp-ip。" tabindex="-1">8.Java支持网络编程，可以处理TCP/IP。 <a class="header-anchor" href="#_8-java支持网络编程-可以处理tcp-ip。" aria-label="Permalink to &quot;8.Java支持网络编程，可以处理TCP/IP。&quot;">​</a></h3><h3 id="_9-java语言-先编译再运行。" tabindex="-1">9.Java语言 先编译再运行。 <a class="header-anchor" href="#_9-java语言-先编译再运行。" aria-label="Permalink to &quot;9.Java语言 先编译再运行。&quot;">​</a></h3><h1 id="_2-java语言规范" tabindex="-1"><u style="text-decoration:underline;text-decoration-color:deepskyblue;">2.Java语言规范</u> <a class="header-anchor" href="#_2-java语言规范" aria-label="Permalink to &quot;&lt;u style=&quot;text-decoration: underline; text-decoration-color: deepskyblue;&quot;&gt;2.Java语言规范&lt;/u&gt;&quot;">​</a></h1><h3 id="_1-java-se" tabindex="-1">1.Java SE <a class="header-anchor" href="#_1-java-se" aria-label="Permalink to &quot;1.Java SE&quot;">​</a></h3><blockquote><p>Java平台的标准版，可以用于开发客户端应用程序，应用程序可以单独运行。</p></blockquote><h3 id="_2-java-me" tabindex="-1">2.Java ME <a class="header-anchor" href="#_2-java-me" aria-label="Permalink to &quot;2.Java ME&quot;">​</a></h3><blockquote><p>Java平台的精简版，用于开发移动设备的应用程序。</p></blockquote><h3 id="_3-java-ee" tabindex="-1">3.Java EE <a class="header-anchor" href="#_3-java-ee" aria-label="Permalink to &quot;3.Java EE&quot;">​</a></h3><blockquote><p>Java平台的企业版，用于开发服务器端的应用。</p></blockquote><h1 id="_3-java虚拟机" tabindex="-1"><u style="text-decoration:underline;text-decoration-color:deepskyblue;">3.Java虚拟机</u> <a class="header-anchor" href="#_3-java虚拟机" aria-label="Permalink to &quot;&lt;u style=&quot;text-decoration: underline; text-decoration-color: deepskyblue;&quot;&gt;3.Java虚拟机&lt;/u&gt;&quot;">​</a></h1><h3 id="_1-jvm其实就是一个字节码解释器。" tabindex="-1">1.JVM其实就是一个字节码解释器。 <a class="header-anchor" href="#_1-jvm其实就是一个字节码解释器。" aria-label="Permalink to &quot;1.JVM其实就是一个字节码解释器。&quot;">​</a></h3><h3 id="_2-字节码最大的好处就是可跨平台执行-可让程序编写一次-到处运行。" tabindex="-1">2.字节码最大的好处就是可跨平台执行，可让程序编写一次，到处运行。 <a class="header-anchor" href="#_2-字节码最大的好处就是可跨平台执行-可让程序编写一次-到处运行。" aria-label="Permalink to &quot;2.字节码最大的好处就是可跨平台执行，可让程序编写一次，到处运行。&quot;">​</a></h3><h1 id="_4-java程序的结构" tabindex="-1"><u style="text-decoration:underline;text-decoration-color:deepskyblue;">4.Java程序的结构</u> <a class="header-anchor" href="#_4-java程序的结构" aria-label="Permalink to &quot;&lt;u style=&quot;text-decoration: underline; text-decoration-color: deepskyblue;&quot;&gt;4.Java程序的结构&lt;/u&gt;&quot;">​</a></h1><h3 id="_1-语句是构成java程序的基本单位之一。" tabindex="-1">1.语句是构成Java程序的基本单位之一。 <a class="header-anchor" href="#_1-语句是构成java程序的基本单位之一。" aria-label="Permalink to &quot;1.语句是构成Java程序的基本单位之一。&quot;">​</a></h3><h3 id="_2-java-application称为java应用程序。java应用程序是指可以再java平台上独立运行的一种程序。" tabindex="-1">2.Java Application称为Java应用程序。Java应用程序是指可以再Java平台上独立运行的一种程序。 <a class="header-anchor" href="#_2-java-application称为java应用程序。java应用程序是指可以再java平台上独立运行的一种程序。" aria-label="Permalink to &quot;2.Java Application称为Java应用程序。Java应用程序是指可以再Java平台上独立运行的一种程序。&quot;">​</a></h3><h3 id="_3-每个应用程序都必须有一个主类-主类是程序执行的起始点-应用程序的主类是包含有main-方法的类-但是应用程序的主类并不一定要求是public类。" tabindex="-1">3.每个应用程序都必须有一个主类，主类是程序执行的起始点，应用程序的主类是包含有main()方法的类，但是应用程序的主类并不一定要求是public类。 <a class="header-anchor" href="#_3-每个应用程序都必须有一个主类-主类是程序执行的起始点-应用程序的主类是包含有main-方法的类-但是应用程序的主类并不一定要求是public类。" aria-label="Permalink to &quot;3.每个应用程序都必须有一个主类，主类是程序执行的起始点，应用程序的主类是包含有main()方法的类，但是应用程序的主类并不一定要求是public类。&quot;">​</a></h3><h1 id="_5-applet" tabindex="-1"><u style="text-decoration:underline;text-decoration-color:deepskyblue;">5.Applet</u> <a class="header-anchor" href="#_5-applet" aria-label="Permalink to &quot;&lt;u style=&quot;text-decoration: underline; text-decoration-color: deepskyblue;&quot;&gt;5.Applet&lt;/u&gt;&quot;">​</a></h1><p>Java Applet 是一种可以嵌入到网页中的小型 Java 程序。尽管在现代开发中使用得越来越少，但了解其基本概念仍然有助于理解 Java 的历史和一些遗留系统。以下是一些关于 Java Applet 的重要知识点：</p><h3 id="_1-applet-的定义" tabindex="-1">1. <strong>Applet 的定义</strong> <a class="header-anchor" href="#_1-applet-的定义" aria-label="Permalink to &quot;1. **Applet 的定义**&quot;">​</a></h3><ul><li>Applet 是一种特殊的 Java 类，继承自 <code>java.applet.Applet</code> 或 <code>javax.swing.JApplet</code>。</li><li>它可以在支持 Java 的浏览器中运行，通常用于展示图形和动画。</li></ul><h3 id="_2-生命周期" tabindex="-1">2. <strong>生命周期</strong> <a class="header-anchor" href="#_2-生命周期" aria-label="Permalink to &quot;2. **生命周期**&quot;">​</a></h3><ul><li>Applet 的生命周期由以下几个方法控制： <ul><li><code>init()</code>: 初始化方法，仅调用一次，用于设置初始状态。</li><li><code>start()</code>: 启动方法，当 Applet 可见时调用。</li><li><code>stop()</code>: 停止方法，当 Applet 不再可见时调用。</li><li><code>destroy()</code>: 销毁方法，当 Applet 被卸载时调用。</li></ul></li></ul><blockquote><p>当一个Applet被下载到本地环境时，不发生的操作是：Applet并不显示出来。 发生的是：1.产生一个Applet主类的实例， 2.对Applet自身进行初始化， 3.启动Applet运行。</p></blockquote><h1 id="随堂小测" tabindex="-1"><u style="text-decoration:underline;text-decoration-color:deepskyblue;">随堂小测</u> <a class="header-anchor" href="#随堂小测" aria-label="Permalink to &quot;&lt;u style=&quot;text-decoration: underline; text-decoration-color: deepskyblue;&quot;&gt;随堂小测&lt;/u&gt;&quot;">​</a></h1><p>1.Java程序可以分为Java Application 和 Java Applet两类。（ ） 2Java虚拟机可以在Windows系列，Linux，UNIX，Mac OS等操作系统下执行Java字节码程序。（ ） 3.javac是Java编译器，用来将Java源程序编译成Java字节码的程序。字节码文件名和源文件名相同，扩展名是class。（ ） 4.main（）方法头的定义可以根据情况任意修改。 （ ） 5.<code>appletviewer</code>是Java小应用程序（Applet）浏览器，可以执行HTML文件中的JavaApplet。它是一个模拟浏览器，可以显示Applet的运行结果。 （ ）</p><h1 id="答案" tabindex="-1"><u style="text-decoration:underline;text-decoration-color:deepskyblue;">答案</u> <a class="header-anchor" href="#答案" aria-label="Permalink to &quot;&lt;u style=&quot;text-decoration: underline; text-decoration-color: deepskyblue;&quot;&gt;答案&lt;/u&gt;&quot;">​</a></h1><h2 id="_1-5-正确-正确-正确-错误-正确" tabindex="-1">1-5 正确 正确 正确 错误 正确 <a class="header-anchor" href="#_1-5-正确-正确-正确-错误-正确" aria-label="Permalink to &quot;1-5 正确 正确 正确 错误 正确&quot;">​</a></h2>',40)]))}const p=e(r,[["render",i]]);export{s as __pageData,p as default};
